async function getSitemapUrls(sitemapUrl, logMessage) {
  const urls = new Set();
  const visitedSitemaps = new Set(); // Tekrarlanan sitemap'leri önlemek için

  async function fetchAndParseSitemap(url) {
    if (visitedSitemaps.has(url)) {
      return; // Bu sitemap zaten işlendi
    }
    visitedSitemaps.add(url);

    try {
      await logMessage(`Sitemap işleniyor: ${url}`);
      const response = await fetch(url, { cf: { cacheTtl: 0 } });
    if (!response.ok) {
      throw new Error(`HTTP hata kodu: ${response.status}`);
    }
    const text = await response.text();

      // Basit regex ile <loc> etiketlerini bul
      const locRegex = /<loc>(.*?)<\/loc>/g;
            let match;
      const foundUrls = [];
      while ((match = locRegex.exec(text)) !== null) {
        foundUrls.push(match[1]);
      }

      if (foundUrls.length === 0) {
        await logMessage(`Hiç <loc> etiketi bulunamadı: ${url}`);
        return;
      }
      
      // Bulunan URL'lerin sitemap mi yoksa normal URL mi olduğunu kontrol et
      for (const foundUrl of foundUrls) {
        if (foundUrl.endsWith('.xml')) {
          // Bu bir alt sitemap, tekrar işle
          await fetchAndParseSitemap(foundUrl);
        } else {
          // Bu normal bir URL, sete ekle
          urls.add(foundUrl);
        }
      }
    } catch (e) {
      await logMessage(`Sitemap alınırken veya ayrıştırılırken hata oluştu ${url}: ${e.message}`);
    }
  }

  await fetchAndParseSitemap(sitemapUrl);
  return urls;
}

async function getGoogleAuthClient(logMessage, serviceAccountEmail, privateKey) {
  if (!serviceAccountEmail || !privateKey) {
    throw new Error('Google Hizmet Hesabı kimlik bilgileri (email veya private key) eksik.');
  }

  // Lenient Base64 decoding polyfill (atob replacement)
  // This version ignores invalid characters and doesn't check for length validity.
  function base64Decode(str) {
    const base64_map = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
    let decoded = "";
    let value = 0;
    let bits = 0;
    let index;
    // The loop ignores characters not in the base64 map, including newlines and padding.
    for (var i = 0; i < str.length; i++) {
        index = base64_map.indexOf(str[i]);
        if (index === -1) continue;
        value = (value << 6) | index;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            decoded += String.fromCharCode((value >> bits) & 0xFF);
        }
    }
    return decoded;
  }

  const jwtHeader = {
    alg: 'RS256',
    typ: 'JWT',
  };

  const now = Math.floor(Date.now() / 1000);
  const jwtPayload = {
    iss: serviceAccountEmail,
    scope: 'https://www.googleapis.com/auth/indexing https://www.googleapis.com/auth/webmasters.readonly',
    aud: 'https://oauth2.googleapis.com/token',
    exp: now + 3600, // 1 saat geçerlilik süresi
    iat: now,
  };

  const base64Header = btoa(JSON.stringify(jwtHeader)).replace(/=/g, '');
  const base64Payload = btoa(JSON.stringify(jwtPayload)).replace(/=/g, '');
  const assertion = `${base64Header}.${base64Payload}`;

  // The new polyfill will handle cleaning, so we just pass the key.
  let decodedKey;
  try {
    decodedKey = base64Decode(privateKey);
  } catch (error) {
    console.error('DEBUG: Lenient base64Decode() hatası:', error.message);
    throw new Error(`base64Decode() hatası: ${error.message}`);
  }

  const privateKeyCrypto = await crypto.subtle.importKey(
    'pkcs8',
    Uint8Array.from(decodedKey, c => c.charCodeAt(0)),
    { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
    false,
    ['sign']
  );

  const signature = await crypto.subtle.sign(
    { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
    privateKeyCrypto,
    new TextEncoder().encode(assertion)
  );

  const base64Signature = btoa(String.fromCharCode(...new Uint8Array(signature)))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');

  const signedJwt = `${assertion}.${base64Signature}`;

  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${signedJwt}`,
  });

  if (!response.ok) {
    const errorBody = await response.text();
    await logMessage(`Google Token Alınamadı. Status: ${response.status}, Body: ${errorBody}`);
    throw new Error(`Google Token Alınamadı. Status: ${response.status}`);
  }

  const tokenData = await response.json();
  return tokenData.access_token;
}

async function checkUrlIndexingStatus(accessToken, url, logMessage) {
  const INSPECTION_API_URL = 'https://searchconsole.googleapis.com/v1/urlInspection/index:inspect';
  
  // URL'yi encode et
  const encodedUrl = encodeURIComponent(url);
  
  const body = {
    inspectionUrl: url,
    siteUrl: 'https://galaktikuzay.com'
  };

  try {
    const response = await fetch(INSPECTION_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${accessToken}`,
      },
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      const errorText = await response.text();
      logMessage(`URL inspection API hatası: ${response.status} ${response.statusText} - ${errorText}`);
      return null;
    }

    const responseData = await response.json();
    
    // URL'nin durumunu kontrol et
    if (responseData.inspectionResult && responseData.inspectionResult.indexStatusResult) {
      const indexStatus = responseData.inspectionResult.indexStatusResult.indexStatus;
      const coverageState = responseData.inspectionResult.indexStatusResult.coverageState;
      
      logMessage(`URL inspection sonucu: ${url} - Durum: ${indexStatus}, Coverage: ${coverageState}`);
      
      return {
        indexStatus: indexStatus,
        coverageState: coverageState,
        lastCrawlTime: responseData.inspectionResult.indexStatusResult.lastCrawlTime,
        pageFetchState: responseData.inspectionResult.indexStatusResult.pageFetchState
      };
    }
    
    return null;
  } catch (e) {
    logMessage(`URL inspection sırasında hata: ${e.message}`);
    return null;
  }
}

async function requestIndexing(accessToken, url, logMessage) {
  const INDEXING_API_URL = 'https://indexing.googleapis.com/v3/urlNotifications:publish';

  const body = {
    url: url,
    type: 'URL_UPDATED',
  };

  const response = await fetch(INDEXING_API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${accessToken}`,
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Dizine ekleme talebi gönderilirken hata oluştu: ${response.status} ${response.statusText} - ${errorText}`);
  }

  const responseData = await response.json();
  logMessage(`Dizine ekleme talebi başarıyla gönderildi: ${url}. Yanıt: ${JSON.stringify(responseData)}`);
}

async function sendReport(logs, indexedUrls, logMessage, senderEmail, receiverEmail) {
  // İstatistikleri hesapla
  const totalUrlsMatch = logs.find(log => log.includes("Sitemap'ten") && log.includes("adet URL bulundu"));
  const totalUrls = totalUrlsMatch ? (totalUrlsMatch.match(/\d+/)?.[0] || '0') : '0';
  const indexedCount = indexedUrls.length;
  const errorCount = logs.filter(log => log.includes('hata') || log.includes('Hata') || log.includes('istisna') || log.includes('❌')).length;
  const successRate = parseInt(totalUrls) > 0 ? ((indexedCount / parseInt(totalUrls)) * 100).toFixed(1) : '0.0';

  // URL kategorilerini analiz et
  const urlCategories = analyzeUrlCategories(indexedUrls);
  
  const reportSubject = `🚀 Galaktik Uzay SEO Raporu - ${new Date().toLocaleDateString('tr-TR')} (${indexedCount} URL işlendi)`;
  
  // Metin formatında rapor içeriği
  const reportBodyText = generateTextReport(logs, indexedUrls, {
    totalUrls,
    indexedCount,
    errorCount,
    successRate,
    urlCategories,
    timestamp: new Date().toLocaleString('tr-TR')
  });

  // Raporu Telegram ile gönder
  const reportSent = await sendWithTelegram(reportSubject, reportBodyText, logMessage);
  
  if (reportSent) {
    await logMessage(`🚀 Otomasyon raporu Telegram ile başarıyla gönderildi.`);
  } else {
    await logMessage(`❌ Telegram raporu gönderilemedi. Lütfen yapılandırmayı kontrol edin.`);
  }
}

function analyzeUrlCategories(urls) {
  const categories = {
    'Ana Sayfa': 0,
    'Blog': 0,
    'Ürün': 0,
    'Kategori': 0,
    'Diğer': 0
  };

  urls.forEach(url => {
    if (url.includes('/blog/') || url.includes('/post/')) {
      categories['Blog']++;
    } else if (url.includes('/urun/') || url.includes('/product/')) {
      categories['Ürün']++;
    } else if (url.includes('/kategori/') || url.includes('/category/')) {
      categories['Kategori']++;
    } else if (url === 'https://galaktikuzay.com/' || url === 'https://galaktikuzay.com') {
      categories['Ana Sayfa']++;
    } else {
      categories['Diğer']++;
    }
  });

  return categories;
}

