async function sendWithTelegram(subject, textContent, logMessage) {
  try {
    await logMessage('Telegram ile rapor gönderilmeye çalışılıyor...');
    
    // Telegram Bot Token ve Chat ID'nizi buraya yazın
    const botToken = '7301046008:AAGpYNjdY6hdjGiuGfTcfW168YpeTCLiANc'; // BotFather'dan aldığınız token
    const chatId = '1104321474'; // Chat ID'niz (Özgür Güler)
    
    if (!botToken || !chatId) {
      await logMessage('Telegram bot bilgileri (token veya chat ID) eksik.');
      return false;
    }
    
    // Mesajı 4096 karakter sınırına göre böl
    const message = `*${subject}*\n\n${textContent}`;
    const chunks = [];
    for (let i = 0; i < message.length; i += 4096) {
      chunks.push(message.substring(i, i + 4096));
    }

    for (const chunk of chunks) {
      const telegramResponse = await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          chat_id: chatId,
          text: chunk,
          parse_mode: 'Markdown'
        }),
      });

      if (!telegramResponse.ok) {
        const errorText = await telegramResponse.text();
        await logMessage(`❌ Telegram hatası (parça gönderimi): ${telegramResponse.status} - ${errorText}`);
        return false; // Bir parça bile başarısız olursa dur
      }
      // Parçalar arasında kısa bir bekleme
      await new Promise(resolve => setTimeout(resolve, 300));
    }

    await logMessage('✅ Telegram ile rapor başarıyla gönderildi.');
    return true;
  } catch (e) {
    await logMessage(`❌ Telegram istisna hatası: ${e.message}`);
    return false;
  }
}

